class InsufficientFunds(Exception):
    pass


def balance(store, wallet):
    """The wallet's balance in cents, 0 for a wallet the store hasn't seen."""
    return store.get(wallet) or 0


def _debit(store, wallet, cents):
    """Take cents from the wallet, raising InsufficientFunds when it holds less.

    The check and the write are one compare-and-put on the value that was checked, so a concurrent
    writer makes us re-read and re-check rather than letting the wallet go below zero.
    """
    while True:
        old = store.get(wallet)
        available = old or 0
        if available < cents:
            raise InsufficientFunds(wallet)
        if store.compare_and_put(wallet, old, available - cents):
            return


def _add(store, wallet, cents):
    """Add cents to the wallet. A concurrent writer makes us re-read and retry, so no update is lost."""
    while True:
        old = store.get(wallet)
        if store.compare_and_put(wallet, old, (old or 0) + cents):
            return


def credit(store, wallet, cents):
    """Add cents to the wallet."""
    _add(store, wallet, cents)


def transfer(store, src, dst, cents):
    """Move cents from src to dst; raise InsufficientFunds when src holds less.

    The two wallets' locks are taken in sorted order, so opposing transfers (A to B and B to A) cannot
    deadlock. A transfer to the same wallet takes no lock (the store's locks are not reentrant) and
    changes nothing.
    """
    if cents < 0:
        raise ValueError(f"transfer amount must not be negative: {cents}")
    if src == dst:
        if balance(store, src) < cents:
            raise InsufficientFunds(src)
        return
    first, second = sorted((src, dst))
    with store.lock(first), store.lock(second):
        _debit(store, src, cents)
        _add(store, dst, cents)

